import{_ as e,o as a,c as r,a3 as i}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"技术决策总览","description":"","frontmatter":{"title":"技术决策总览"},"headers":[],"relativePath":"frontend/decisions/index.md","filePath":"frontend/decisions/index.md","lastUpdated":1784378817000}'),d={name:"frontend/decisions/index.md"};function n(o,t,l,s,h,c){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="技术决策" tabindex="-1">技术决策 <a class="header-anchor" href="#技术决策" aria-label="Permalink to &quot;技术决策&quot;">​</a></h1><p>技术决策不是寻找脱离场景的“最佳方案”，而是在明确约束下选择代价可接受的方案。高质量决策需要事实、比较标准、风险意识和可追溯记录，也需要知道何时应该推迟、试验或撤销决定。</p><p>本模块不重复介绍工具和框架的全部知识，而是聚焦它们进入真实项目时的选择条件、组合方式和长期成本。</p><h2 id="决策地图" tabindex="-1">决策地图 <a class="header-anchor" href="#决策地图" aria-label="Permalink to &quot;决策地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>典型问题</th><th>主要评价维度</th></tr></thead><tbody><tr><td><a href="/frontend/decisions/decision-framework">决策方法</a></td><td>如何形成、记录、复盘决定并规划长期技术路线</td><td>目标、证据、风险、可逆性和反馈周期</td></tr><tr><td><a href="/frontend/decisions/architecture/modularization">架构决策</a></td><td>如何划分系统以及是否引入复杂架构</td><td>规模、边界、独立交付和演进成本</td></tr><tr><td><a href="/frontend/decisions/rendering/csr-ssr">渲染决策</a></td><td>CSR、SSR、SSG、ISR 或边缘渲染如何选择</td><td>SEO、个性化、缓存、延迟和运行成本</td></tr><tr><td><a href="/frontend/decisions/tooling/framework-selection">工具链决策</a></td><td>框架、元框架、包管理器和构建工具如何选择</td><td>团队能力、生态、性能、迁移和维护周期</td></tr><tr><td><a href="/frontend/decisions/data/state-management">状态与数据决策</a></td><td>状态、API、实时通信和缓存方案如何组合</td><td>一致性、复杂度、延迟、离线和服务端能力</td></tr><tr><td><a href="/frontend/decisions/ui/css-strategy">UI 决策</a></td><td>样式、组件库和设计系统是否值得建设</td><td>一致性、复用范围、定制成本和治理能力</td></tr><tr><td><a href="/frontend/decisions/quality/testing-strategy">质量与交付决策</a></td><td>测试、监控、采购、迁移和发布如何投入</td><td>风险、收益、组织能力和退出成本</td></tr></tbody></table><h2 id="决策流程" tabindex="-1">决策流程 <a class="header-anchor" href="#决策流程" aria-label="Permalink to &quot;决策流程&quot;">​</a></h2><ol><li><strong>定义问题</strong>：写清业务目标、受影响对象和不做决定的后果。</li><li><strong>列出约束</strong>：包括时间、团队、兼容性、合规、预算和既有系统。</li><li><strong>确定标准</strong>：在比较方案前确定评价维度及其优先级。</li><li><strong>形成选项</strong>：至少保留现状作为一个方案，避免把预设答案包装成比较。</li><li><strong>收集证据</strong>：通过文档、原型、基准测试和历史数据降低关键不确定性。</li><li><strong>评估代价</strong>：同时考虑引入、运行、迁移、退出和认知成本。</li><li><strong>记录决定</strong>：使用 <a href="/frontend/decisions/adr">ADR</a> 保存背景、选择、后果和复查条件。</li><li><strong>验证与复盘</strong>：观察真实结果，在触发条件出现时重新评估。</li></ol><h2 id="决策分级" tabindex="-1">决策分级 <a class="header-anchor" href="#决策分级" aria-label="Permalink to &quot;决策分级&quot;">​</a></h2><p>并非所有选择都值得召开评审或编写长文档：</p><ul><li>局部且容易撤销的决定，应快速试验并保留基本记录。</li><li>跨模块、跨团队或迁移成本高的决定，需要明确评审和 ADR。</li><li>信息不足但影响重大的决定，应先通过原型或限量发布获取证据。</li><li>已有组织标准覆盖的决定，优先复用标准，同时允许基于证据提出例外。</li></ul><h2 id="与其他模块的边界" tabindex="-1">与其他模块的边界 <a class="header-anchor" href="#与其他模块的边界" aria-label="Permalink to &quot;与其他模块的边界&quot;">​</a></h2><ul><li><a href="/frontend/guide/core/">核心知识</a>说明候选技术的能力和限制。</li><li><a href="/frontend/guide/engineering/">工程体系</a>提供测试、性能、发布和监控等评价手段。</li><li>本模块组织比较过程并记录选择，不替代具体实现。</li><li><a href="/frontend/practices/">项目实战</a>检验决定在真实约束下产生的结果。</li></ul><h2 id="高质量决策的标准" tabindex="-1">高质量决策的标准 <a class="header-anchor" href="#高质量决策的标准" aria-label="Permalink to &quot;高质量决策的标准&quot;">​</a></h2><ul><li>问题和约束比方案描述更清楚。</li><li>比较维度在结论之前确定，并且可以被他人审查。</li><li>既记录收益，也记录被接受的缺点和退出成本。</li><li>明确决定的负责人、有效范围、复查时间或触发条件。</li><li>新证据出现时能够修正决定，而不是维护个人立场。</li></ul>',14)])])}const g=e(d,[["render",n]]);export{u as __pageData,g as default};
